async function medical_evidence_search(params, userSettings, resources) {
  // Shared Core Engine for Gemini Chat Hub: Medical Grounded Search Plugin (v2.0.0)
  // Zero-CORS node:vm server runtime — Gemini 3.5 Flash-Lite & Gemini 4+ + Gemini Decision 1

  const startTimeMs = Date.now();
  const HARD_BUDGET_MS = 78e3;
  const parentSignal = resources && resources.signal || null;
  const xmlNonce = ((Math.floor(Math.random() * 16777215) ^ (startTimeMs & 16777215)) >>> 0).toString(16).padStart(6, "0");

  function xmlTag(name) {
    return `${name}_${xmlNonce}`;
  }
  function elapsedMs() {
    return Date.now() - startTimeMs;
  }
  function remainingBudgetMs() {
    return Math.max(0, HARD_BUDGET_MS - elapsedMs());
  }
  function isAborted() {
    return Boolean(parentSignal && parentSignal.aborted);
  }
  function clamp(num, min, max) {
    return Math.max(min, Math.min(max, num));
  }
  function unique(arr) {
    return Array.from(new Set((arr || []).filter(Boolean)));
  }
  function toArray(v) {
    return Array.isArray(v) ? v.filter(Boolean) : [];
  }
  function truncate(text, max) {
    return !text || text.length <= max ? text || "" : text.slice(0, max);
  }
  function shortHash(str) {
    let h = 2166136261;
    const s = String(str || "");
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return (h >>> 0).toString(16).padStart(8, "0");
  }

  const uSettings = userSettings || {};
  const vaultRef = (typeof vault !== "undefined" && vault) || (resources && resources.vault) || null;
  const storageRef = (typeof storage !== "undefined" && storage) || (typeof localStorage !== "undefined" && localStorage && typeof localStorage.get === "function" ? localStorage : null) || (resources && resources.storage) || null;
  const wsRef = (typeof workspace !== "undefined" && workspace) || (resources && resources.workspace) || null;

  function resolveSecret(...keys) {
    for (const k of keys) {
      if (uSettings[k] && String(uSettings[k]).trim() && !String(uSettings[k]).includes("{{")) {
        return String(uSettings[k]).trim();
      }
    }
    if (vaultRef && typeof vaultRef.getSecret === "function") {
      for (const k of keys) {
        const val = vaultRef.getSecret(k) || vaultRef.getSecret(k.toUpperCase());
        if (val && String(val).trim()) return String(val).trim();
      }
    }
    return "";
  }

  const geminiApiKey = resolveSecret("google_api_key", "gemini_api_key", "GOOGLE_API_KEY", "GEMINI_API_KEY", "GEMINI_PAID_API_KEY", "GEMINI_FREE_API_KEY");
  const ncbiApiKey = resolveSecret("ncbi_api_key", "NCBI_API_KEY");
  const openfdaApiKey = resolveSecret("openfda_api_key", "OPENFDA_API_KEY");

  const rawModelId = String(uSettings.generative_model || "gemini-3.5-flash-lite").trim();
  const generativeModel = rawModelId.replace(/^(~?google\/|models\/)/i, "") || "gemini-3.5-flash-lite";
  const verificationEngine = uSettings.verification_engine || "hybrid_auto";
  const enableHop2Setting = uSettings.enable_hop2_verification || "on_failure_only";
  const actionOnError = uSettings.action_on_error || "return_diagnostic_json";

  const geminiDirectUrl = "https://generativelanguage.googleapis.com/v1beta/interactions";
  const decisionsDirectUrl = "https://generativelanguage.googleapis.com/v1beta/decisions";

  const SIFT_SCALE_NOTE = "All sift_audit.metrics and overall_medical_weight are scaled [0.0, 1.0] where 1.0 = highest clinical authority / human solidity / currency; credibility_level: 0=Tier 1 Authoritative, 1=Tier 2 Supporting, 2=Tier 3 Anecdotal/Low-Weight.";

  const today = (new Date()).toISOString().split("T")[0];
  const currentYear = today.split("-")[0];
  let transportState = "healthy";
  let decisionsCircuitOpen = false;
  const diagnostics = {
    plugin_version: "2.0.0",
    generative_model: generativeModel,
    router_mode: "not_run",
    decisions_api_calls: 0,
    decisions_api_status: verificationEngine === "off" || verificationEngine === "generative_fallback" ? "disabled" : "not_invoked",
    entailment_gate_status: "not_run",
    generative_calls: 0,
    incomplete_generations: 0,
    json_repairs: 0,
    quotes_verified_direct: 0,
    quotes_recovered: 0,
    claims_rejected_unverified_quote: 0,
    hydration_failures: [],
    total_tokens: 0,
    api_calls: {}
  };

  function trackApiCall(apiName, ok) {
    if (!diagnostics.api_calls[apiName]) {
      diagnostics.api_calls[apiName] = { ok: 0, fail: 0 };
    }
    if (ok) diagnostics.api_calls[apiName].ok += 1;
    else diagnostics.api_calls[apiName].fail += 1;
  }

  function recordUsageTokens(usage) {
    if (!usage || typeof usage !== "object") return;
    const total = Number(usage.total_tokens || usage.totalTokenCount || ((usage.input_tokens || usage.promptTokenCount || 0) + (usage.output_tokens || usage.candidatesTokenCount || 0)) || 0);
    if (Number.isFinite(total) && total > 0) {
      diagnostics.total_tokens += total;
    }
  }

  async function fetchWithTimeout(url, options, timeoutMs) {
    if (isAborted()) {
      throw new Error("aborted_by_caller");
    }
    const budgetLeft = remainingBudgetMs();
    if (budgetLeft <= 1200) {
      throw new Error("execution_budget_exhausted");
    }
    const effectiveTimeout = Math.max(1500, Math.min(timeoutMs, budgetLeft - 1000));
    const controller = new AbortController();
    const onParentAbort = () => controller.abort();
    if (parentSignal && typeof parentSignal.addEventListener === "function") {
      parentSignal.addEventListener("abort", onParentAbort, { once: true });
    }
    const timer = setTimeout(() => controller.abort(), effectiveTimeout);
    try {
      return await fetch(url, { ...options, signal: controller.signal });
    } finally {
      clearTimeout(timer);
      if (parentSignal && typeof parentSignal.removeEventListener === "function") {
        parentSignal.removeEventListener("abort", onParentAbort);
      }
    }
  }

  let lastNcbiCallTimeMs = 0;
  async function paceNcbiRequest(url) {
    if (!/ncbi\.nlm\.nih\.gov/i.test(String(url || ""))) return;
    const minGap = ncbiApiKey ? 150 : 420;
    const now = Date.now();
    const scheduled = Math.max(now, lastNcbiCallTimeMs + minGap);
    lastNcbiCallTimeMs = scheduled;
    const waitMs = scheduled - now;
    if (waitMs > 0) {
      await new Promise((r) => setTimeout(r, waitMs));
    }
  }

  async function fetchPublicJson(url, apiName = "public_api", timeoutMs = 10000, { allowNotFound = false } = {}) {
    let lastError = "fetch_failed";
    for (let attempt = 0; attempt < 3; attempt++) {
      if (isAborted()) return { ok: false, status: 0, data: null, error: "aborted_by_caller" };
      try {
        await paceNcbiRequest(url);
        const res = await fetchWithTimeout(url, {
          headers: {
            "User-Agent": "GeminiMedicalSearch/2.0 (https://ai.google.dev)",
            "Accept": "application/json,*/*"
          }
        }, timeoutMs);
        if (res.status === 429 && attempt < 2 && remainingBudgetMs() > 8000) {
          await new Promise((r) => setTimeout(r, 950 + attempt * 450));
          continue;
        }
        if (allowNotFound && res.status === 404) {
          return { ok: false, status: 404, data: null, error: "not_found" };
        }
        if (!res.ok) {
          lastError = `HTTP_${res.status}`;
          break;
        }
        const text = await res.text();
        let parsed = null;
        try {
          parsed = JSON.parse(text);
        } catch (je) {
          if (allowNotFound) return { ok: false, status: res.status, data: null, error: "non_json_not_available" };
          throw je;
        }
        trackApiCall(apiName, true);
        return { ok: true, status: res.status, data: parsed, error: null };
      } catch (e) {
        lastError = e.message || "fetch_exception";
        break;
      }
    }
    trackApiCall(apiName, false);
    return { ok: false, status: 0, data: null, error: lastError };
  }

  async function fetchPublicText(url, apiName = "public_api", timeoutMs = 12000, { allowNotFound = false } = {}) {
    let lastError = "fetch_failed";
    for (let attempt = 0; attempt < 2; attempt++) {
      if (isAborted()) return { ok: false, status: 0, text: "", lastModified: null, error: "aborted_by_caller" };
      try {
        await paceNcbiRequest(url);
        const res = await fetchWithTimeout(url, {
          headers: {
            "User-Agent": "Mozilla/5.0 (compatible; GeminiMedicalSearch/2.0; +https://ai.google.dev)",
            "Accept": "application/xml,text/xml,text/html,text/plain,*/*"
          }
        }, timeoutMs);
        if (res.status === 429 && attempt === 0 && remainingBudgetMs() > 8000) {
          await new Promise((r) => setTimeout(r, 650));
          continue;
        }
        if (allowNotFound && res.status === 404) {
          return { ok: false, status: 404, text: "", lastModified: null, error: "not_found" };
        }
        if (!res.ok) {
          lastError = `HTTP_${res.status}`;
          break;
        }
        const text = await res.text();
        trackApiCall(apiName, true);
        return { ok: true, status: res.status, text, lastModified: res.headers.get("last-modified"), error: null };
      } catch (e) {
        lastError = e.message || "fetch_exception";
        break;
      }
    }
    trackApiCall(apiName, false);
    return { ok: false, status: 0, text: "", lastModified: null, error: lastError };
  }

  async function storageCacheGet(key, maxAgeMs) {
    if (!storageRef || typeof storageRef.get !== "function") return null;
    try {
      const entry = await storageRef.get(key);
      if (entry && entry.timestamp && Date.now() - entry.timestamp < maxAgeMs) {
        return entry.data;
      }
    } catch (e) {}
    return null;
  }

  async function storageCacheSet(key, data) {
    if (!storageRef || typeof storageRef.set !== "function") return;
    try {
      await storageRef.set(key, { data, timestamp: Date.now() });
    } catch (e) {}
  }

  function decodeHtmlEntities(str) {
    if (!str) return "";
    return String(str)
      .replace(/&nbsp;/gi, " ")
      .replace(/&lt;/gi, "<")
      .replace(/&gt;/gi, ">")
      .replace(/&quot;/gi, '"')
      .replace(/&#39;|&apos;/gi, "'")
      .replace(/&ndash;/gi, "-")
      .replace(/&mdash;/gi, "--")
      .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => {
        const code = parseInt(hex, 16);
        return code > 0 && code <= 1114111 ? String.fromCodePoint(code) : "";
      })
      .replace(/&#(\d+);/g, (_, dec) => {
        const code = parseInt(dec, 10);
        return code > 0 && code <= 1114111 ? String.fromCodePoint(code) : "";
      })
      .replace(/&amp;/gi, "&");
  }

  function cleanTextPreserveLines(text) {
    if (!text) return "";
    return String(text)
      .replace(/\r\n?/g, "\n")
      .replace(/\u0000/g, "")
      .replace(/\t/g, "  ")
      .replace(/[ \u00A0]+\n/g, "\n")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  }

  function sanitizeUntrustedXml(text) {
    if (!text) return "";
    return String(text)
      .replace(new RegExp(`<(\\/?[a-zA-Z0-9_]+_${xmlNonce})\\b`, "gi"), "<\\$1")
      .replace(/<(\/?(?:evidence_lattice|sources_matrix|clinical_query_task|sources_dossier|candidate_chunks|query_objective|medical_request|reconciliation_notes))\b/gi, "<\\$1")
      .replace(/(---\s*SOURCE\s+S?\d+)/gi, "[QUOTED] $1");
  }

  function stripXmlTags(str) {
    if (!str) return "";
    return cleanTextPreserveLines(
      decodeHtmlEntities(
        String(str)
          .replace(/<br\s*\/?>/gi, "\n")
          .replace(/<\/(p|paragraph|item|row|tr|li|div|title)>/gi, "\n")
          .replace(/<(td|th)\b[^>]*>/gi, " | ")
          .replace(/<[^>]+>/g, " ")
      ).replace(/[ \t]{2,}/g, " ")
    );
  }

  function normalizeIsoDate(rawDate) {
    if (!rawDate) return null;
    const s = String(rawDate).trim();
    if (/^\d{8}$/.test(s)) {
      return `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}`;
    }
    const isoMatch = s.match(/\b(19\d{2}|20\d{2})-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])\b/);
    if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;
    const ymMatch = s.match(/\b(19\d{2}|20\d{2})[\s/-](Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec|\d{2})\b/i);
    if (ymMatch) {
      const p = Date.parse(`${ymMatch[1]} ${ymMatch[2]} 01 UTC`);
      if (!Number.isNaN(p)) return new Date(p).toISOString().split("T")[0];
    }
    const parsed = Date.parse(s);
    if (!Number.isNaN(parsed)) {
      const d = new Date(parsed);
      const yr = d.getUTCFullYear();
      if (yr >= 1970 && yr <= Number(currentYear) + 1) {
        return d.toISOString().split("T")[0];
      }
    }
    if (/^(19\d{2}|20\d{2})$/.test(s)) return `${s}-01-01`;
    return null;
  }

  function safeDomain(url) {
    try {
      return new URL(url).hostname.toLowerCase().replace(/^www\./, "");
    } catch (e) {
      return "unknown";
    }
  }

  function safePathname(url) {
    try {
      return new URL(url).pathname || "/";
    } catch (e) {
      return "/";
    }
  }

  function isSafePublicHttpUrl(rawUrl) {
    try {
      const u = new URL(String(rawUrl || "").trim());
      if (u.protocol !== "http:" && u.protocol !== "https:") return false;
      const host = u.hostname.toLowerCase().replace(/^\[|\]$/g, "");
      if (!host || host === "localhost" || host === "0.0.0.0" || host === "::1" || host.endsWith(".local") || host.endsWith(".internal")) {
        return false;
      }
      if (/^127\./.test(host) || /^10\./.test(host) || /^192\.168\./.test(host) || /^169\.254\./.test(host)) {
        return false;
      }
      const m172 = host.match(/^172\.(\d+)\./);
      if (m172 && Number(m172[1]) >= 16 && Number(m172[1]) <= 31) return false;
      if (/^(fc|fd|fe80:)/i.test(host)) return false;
      return true;
    } catch (e) {
      return false;
    }
  }

  function extractPublishedDateFromHtml(htmlString) {
    if (!htmlString) return null;
    const headSlice = String(htmlString).slice(0, 45000);
    const metaPatterns = [
      /<meta[^>]+(?:property|name|itemprop)\s*=\s*["'](?:article:published_time|article:modified_time|og:published_time|publication_date|publish_date|pubdate|datePublished|dc\.date|dcterms\.created|dcterms\.modified)["'][^>]+content\s*=\s*["']([^"']+)["']/i,
      /<meta[^>]+content\s*=\s*["']([^"']+)["'][^>]+(?:property|name|itemprop)\s*=\s*["'](?:article:published_time|article:modified_time|og:published_time|publication_date|publish_date|pubdate|datePublished|dc\.date|dcterms\.created)["']/i,
      /"datePublished"\s*:\s*"([^"]{8,40})"/i,
      /<time[^>]+datetime\s*=\s*["']([^"']{8,40})["']/i
    ];
    for (const pat of metaPatterns) {
      const m = headSlice.match(pat);
      if (m && m[1]) {
        const norm = normalizeIsoDate(m[1]);
        if (norm) return norm;
      }
    }
    return null;
  }

  function extractTitleFromHtml(htmlString) {
    if (!htmlString) return null;
    const m = String(htmlString).slice(0, 25000).match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    if (!m || !m[1]) return null;
    return cleanTextPreserveLines(decodeHtmlEntities(m[1].replace(/\s+/g, " "))).slice(0, 240);
  }

  function extractStructuredHtml(htmlString, maxChars = 60000) {
    if (!htmlString) return { text: "", publishedDate: null, extractedTitle: null };
    const publishedDate = extractPublishedDateFromHtml(htmlString);
    const extractedTitle = extractTitleFromHtml(htmlString);
    let working = String(htmlString)
      .replace(/<!--[\s\S]*?-->/g, " ")
      .replace(/<(script|style|noscript|svg|canvas|iframe|template|form)\b[\s\S]*?<\/\1>/gi, " ");
    const mainMatch = working.match(/<(main|article)\b[^>]*>([\s\S]*?)<\/\1>/i);
    if (mainMatch && mainMatch[2] && mainMatch[2].replace(/<[^>]+>/g, "").trim().length > 400) {
      working = mainMatch[2];
    } else {
      working = working.replace(/<(nav|footer|header|aside)\b[\s\S]*?<\/\1>/gi, " ");
    }
    working = working
      .replace(/<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/gi, (_, lvl, inner) => {
        const hTxt = decodeHtmlEntities(inner.replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim();
        return hTxt ? `\n\n${"#".repeat(Number(lvl))} ${hTxt}\n` : "\n";
      })
      .replace(/<li\b[^>]*>/gi, "\n- ")
      .replace(/<\/tr>/gi, "\n")
      .replace(/<(td|th)\b[^>]*>/gi, " | ")
      .replace(/<br\s*\/?>/gi, "\n")
      .replace(/<\/(p|div|section|article|blockquote|ul|ol|table|dl|dt|dd)>/gi, "\n\n")
      .replace(/<[^>]+>/g, " ");
    const decoded = decodeHtmlEntities(working)
      .replace(/[ \t]+\|/g, " |")
      .replace(/\|[ \t]+/g, "| ")
      .replace(/[ \t]{2,}/g, " ");
    return {
      text: cleanTextPreserveLines(decoded).slice(0, maxChars),
      publishedDate,
      extractedTitle
    };
  }

  function repairTruncatedJson(rawText) {
    if (!rawText) return null;
    let s = String(rawText).trim();
    if (s.startsWith("```")) {
      s = s.replace(/^```(?:json)?\s*\n?/i, "").replace(/\n?```\s*$/i, "").trim();
    }
    const firstStart = s.search(/[\[{]/);
    if (firstStart < 0) return null;
    if (firstStart > 0) s = s.slice(firstStart);
    let out = "";
    const stack = [];
    let inString = false;
    let escaped = false;
    let started = false;
    for (let i = 0; i < s.length; i++) {
      const ch = s[i];
      if (inString) {
        if (ch === "\n") {
          out += "\\n";
          escaped = false;
          continue;
        }
        if (ch === "\r") {
          out += "\\r";
          escaped = false;
          continue;
        }
        out += ch;
        if (escaped) escaped = false;
        else if (ch === "\\") escaped = true;
        else if (ch === '"') inString = false;
        continue;
      }
      if (ch === '"') {
        inString = true;
        out += ch;
      } else if (ch === "{") {
        started = true;
        stack.push("}");
        out += ch;
      } else if (ch === "[") {
        started = true;
        stack.push("]");
        out += ch;
      } else if (ch === "}" || ch === "]") {
        out = out.replace(/,\s*$/, "");
        if (stack.length > 0 && stack[stack.length - 1] === ch) {
          stack.pop();
          out += ch;
          if (started && stack.length === 0) break;
        }
      } else {
        out += ch;
      }
    }
    if (inString) {
      if (escaped) out = out.slice(0, -1);
      else out = out.replace(/\\u[0-9a-fA-F]{0,3}$/, "");
      out += '"';
    }
    out = out.replace(/,\s*$/, "");
    if (stack.length > 0 && stack[stack.length - 1] === "}") {
      const danglingKeyMatch = out.match(/([,{]\s*)"[^"]*"\s*$/);
      if (danglingKeyMatch) {
        out = out.slice(0, out.length - danglingKeyMatch[0].length + danglingKeyMatch[1].length).replace(/,\s*$/, "");
      }
    }
    out = out.replace(/(:\s*)(?:t|tr|tru|f|fa|fal|fals|n|nu|nul|-|\d+\.|\d+[eE][+-]?)$/, "$1null");
    out = out.replace(/(,\s*)(?:t|tr|tru|f|fa|fal|fals|n|nu|nul|-|\d+\.|\d+[eE][+-]?)$/, "");
    if (/:\s*$/.test(out)) out += "null";
    out = out.replace(/,\s*$/, "");
    while (stack.length > 0) out += stack.pop();
    return out;
  }

  function parseStructuredJson(rawText) {
    if (!rawText || typeof rawText !== "string") return { parsed: null, repaired: false, error: "empty_response" };
    const trimmed = rawText.trim();
    try {
      return { parsed: JSON.parse(trimmed), repaired: false, error: null };
    } catch (directErr) {
      try {
        const candidate = repairTruncatedJson(trimmed);
        if (!candidate) return { parsed: null, repaired: false, error: directErr.message };
        const parsed = JSON.parse(candidate);
        diagnostics.json_repairs += 1;
        return { parsed, repaired: true, error: null };
      } catch (repairErr) {
        return { parsed: null, repaired: false, error: directErr.message };
      }
    }
  }

  async function readResponseBufferWithLimit(res, maxBytes) {
    if (res.body && typeof res.body.getReader === "function") {
      const reader = res.body.getReader();
      const chunks = [];
      let total = 0;
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          if (!value) continue;
          total += value.byteLength;
          if (total > maxBytes) {
            try { await reader.cancel(); } catch (e) {}
            return { exceeded: true, buffer: null, byteLength: total };
          }
          chunks.push(value);
        }
      } finally {
        try { reader.releaseLock(); } catch (e) {}
      }
      const merged = Buffer.concat(chunks.map((c) => Buffer.from(c.buffer, c.byteOffset, c.byteLength)), total);
      return { exceeded: false, buffer: merged, byteLength: total };
    }
    const ab = await res.arrayBuffer();
    if (ab.byteLength > maxBytes) {
      return { exceeded: true, buffer: null, byteLength: ab.byteLength };
    }
    return { exceeded: false, buffer: Buffer.from(ab), byteLength: ab.byteLength };
  }

  async function fetchAndHydrateDocument(url, options = {}) {
    const {
      allowPdfMultimodal = true,
      maxPdfBytes = 14 * 1024 * 1024,
      maxTextBytes = 8 * 1024 * 1024,
      enforcePublicUrl = true
    } = options;
    const failResult = { success: false, type: "unknown", is_native_pdf: false, text: "", publishedDate: null };
    if (enforcePublicUrl && !isSafePublicHttpUrl(url)) {
      diagnostics.hydration_failures.push(`blocked_non_public_url: ${truncate(url, 120)}`);
      return failResult;
    }
    try {
      const res = await fetchWithTimeout(url, {
        headers: {
          "User-Agent": "Mozilla/5.0 (compatible; GeminiMedicalSearch/2.0; +https://ai.google.dev)",
          "Accept": "application/pdf,text/csv,text/html,application/xhtml+xml,text/plain,*/*"
        }
      }, 15000);
      if (!res.ok) {
        diagnostics.hydration_failures.push(`http_${res.status}: ${safeDomain(url)}`);
        return failResult;
      }
      const contentType = (res.headers.get("content-type") || "").toLowerCase();
      const lastModifiedHeader = res.headers.get("last-modified");
      const pathnameLower = safePathname(url).toLowerCase();
      const isPdf = contentType.includes("application/pdf") || pathnameLower.endsWith(".pdf");
      const maxAllowed = isPdf ? maxPdfBytes : maxTextBytes;
      const contentLength = Number(res.headers.get("content-length") || 0);
      if (contentLength > maxAllowed) {
        diagnostics.hydration_failures.push(`payload_too_large (${Math.round(contentLength / 1024)}KB): ${safeDomain(url)}`);
        return failResult;
      }
      const readRes = await readResponseBufferWithLimit(res, maxAllowed);
      if (readRes.exceeded || !readRes.buffer || readRes.byteLength < 16) {
        if (readRes.exceeded) diagnostics.hydration_failures.push(`stream_exceeded_limit: ${safeDomain(url)}`);
        return failResult;
      }
      const buf = readRes.buffer;
      const magic = buf.subarray(0, 5).toString("latin1");
      if (allowPdfMultimodal && magic.startsWith("%PDF")) {
        if (buf.byteLength < 64) return failResult;
        return {
          success: true,
          type: "pdf",
          is_native_pdf: true,
          pdf_base64: buf.toString("base64"),
          pdf_byte_length: buf.byteLength,
          mime_type: "application/pdf",
          text: `[NATIVE MULTIMODAL PDF DOCUMENT (${Math.round(buf.byteLength / 1024)} KB) — Evaluated directly via Gemini native vision/document understanding. URL: ${url}]`,
          publishedDate: null,
          lastModified: normalizeIsoDate(lastModifiedHeader)
        };
      }
      const decodedText = new TextDecoder("utf-8", { fatal: false }).decode(buf);
      if (contentType.includes("text/plain") || contentType.includes("text/markdown") || contentType.includes("text/csv") || contentType.includes("application/json")) {
        const cleaned = cleanTextPreserveLines(decodedText).slice(0, 60000);
        return {
          success: cleaned.length > 30,
          type: "text",
          is_native_pdf: false,
          text: cleaned,
          publishedDate: null,
          lastModified: normalizeIsoDate(lastModifiedHeader)
        };
      }
      const parsedHtml = extractStructuredHtml(decodedText, 60000);
      if (parsedHtml.text.length > 80) {
        return {
          success: true,
          type: "html",
          is_native_pdf: false,
          text: parsedHtml.text,
          extractedTitle: parsedHtml.extractedTitle,
          publishedDate: parsedHtml.publishedDate,
          lastModified: normalizeIsoDate(lastModifiedHeader)
        };
      }
    } catch (e) {
      diagnostics.hydration_failures.push(`${safeDomain(url)}: ${e.message || "fetch_failed"}`);
    }
    return failResult;
  }

  async function stageMedicalRecordsToWorkspace(sources, detailMode = "AUTO") {
    if (!wsRef || typeof wsRef.writeFile !== "function" || detailMode === "MINIMAL") return;
    for (const s of sources) {
      if (!s || s.is_native_pdf || !s.text) continue;
      const isLargeOrFullLabel = s.text.length >= 9000 || s.source_api === "openfda_label" || s.source_api === "dailymed_spl" || s.source_api === "pubmed_and_pmc_bioc";
      if (!isLargeOrFullLabel || s.text.length < 4000) continue;
      try {
        const apiSlug = String(s.source_api || "med").replace(/[^a-z0-9_-]/gi, "_").slice(0, 24);
        const fname = `med_${s.handle || `S${s.id}`}_${apiSlug}_${shortHash(s.url || s.title)}.md`;
        const header = `# ${s.title}\nHandle: ${s.handle || `S${s.id}`}\nURL: ${s.url}\nAPI: ${s.source_api}\nStudyType: ${s.study_type}\nPublishedDate: ${s.publishedDate || "UNKNOWN"}\n\n`;
        const res = await wsRef.writeFile(fname, header + s.text, "in");
        s.staged_workspace_files = unique([...(s.staged_workspace_files || []), res?.relativePath || `in/${fname}`]);
      } catch (e) {
        diagnostics.hydration_failures.push(`workspace_stage_failed (${s.source_api}): ${e.message || "write_error"}`);
      }
    }
  }

  function resolveThinkingLevel(modelId, stageDesiredLevel) {
    const m = String(modelId || "").toLowerCase();
    const desired = String(stageDesiredLevel || "medium").toLowerCase();
    if (/omni|image|banana/.test(m) && desired === "medium") return "high";
    if (desired === "xhigh") return /hydrogen|neon/.test(m) ? "xhigh" : "high";
    if (desired === "minimal") return "low";
    if (["low", "medium", "high"].includes(desired)) return desired;
    return "medium";
  }

  function extractTextFromInteraction(data, preferLastStepForJson = false) {
    if (!data) return "";
    if (typeof data.output_text === "string" && data.output_text.length > 0) return data.output_text;
    const stepTexts = [];
    if (Array.isArray(data.steps)) {
      for (const step of data.steps) {
        if ((step.type === "model_output" || !step.type) && Array.isArray(step.content)) {
          const stepParts = [];
          for (const block of step.content) {
            if (block && block.type === "text" && typeof block.text === "string") stepParts.push(block.text);
          }
          const joined = stepParts.join("").trim();
          if (joined) stepTexts.push(joined);
        }
      }
    }
    if (stepTexts.length > 0) {
      if (preferLastStepForJson && stepTexts.length > 1) {
        const last = stepTexts[stepTexts.length - 1];
        if (/^\s*[\[{]/.test(last) || /^\s*```(?:json)?/i.test(last)) return last;
      }
      return stepTexts.join("");
    }
    const parts = [];
    if (Array.isArray(data.outputs)) {
      for (const block of data.outputs) {
        if (block && block.type === "text" && typeof block.text === "string") parts.push(block.text);
      }
    }
    return parts.join("");
  }

  async function callGemini({
    systemInstruction,
    inputBlocks,
    responseSchema,
    thinkingLevel = "medium",
    maxOutputTokens = 65536,
    timeoutMs = 38000
  }) {
    if (!geminiApiKey) {
      return { ok: false, text: "", status: "missing_api_key", error: "Missing Google Gemini API key" };
    }
    if (isAborted()) {
      return { ok: false, text: "", status: "aborted", error: "aborted_by_caller" };
    }
    const resolvedThinking = resolveThinkingLevel(generativeModel, thinkingLevel);
    let currentMaxTokens = clamp(maxOutputTokens || 65536, 8192, 65536);
    const buildPayload = (includeThinking = true, continuationToken = null) => {
      const p = { model: generativeModel };
      p.generation_config = { max_output_tokens: currentMaxTokens };
      if (includeThinking && resolvedThinking) p.generation_config.thinking_level = resolvedThinking;
      if (continuationToken) {
        p.continuation_token = continuationToken;
        return p;
      }
      p.input = inputBlocks;
      if (systemInstruction) p.system_instruction = systemInstruction;
      if (responseSchema) {
        p.response_format = {
          type: "text",
          mime_type: "application/json",
          schema: responseSchema
        };
      }
      return p;
    };
    const headers = {
      "Content-Type": "application/json",
      "x-goog-api-key": geminiApiKey,
      "Api-Revision": "2026-05-20"
    };
    let lastError = "unknown_gemini_error";
    let includeThinking = true;
    let retriedThinking = false;
    let retriedMaxTokens = false;

    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        diagnostics.generative_calls += 1;
        const res = await fetchWithTimeout(geminiDirectUrl, {
          method: "POST",
          headers,
          body: JSON.stringify(buildPayload(includeThinking, null))
        }, timeoutMs);
        const rawBody = await res.text();
        let data = null;
        try { data = JSON.parse(rawBody); } catch (e) {}
        if (!res.ok) {
          const errMsg = data?.error?.message || rawBody.slice(0, 300) || `HTTP ${res.status}`;
          lastError = `HTTP ${res.status}: ${errMsg}`;
          if (res.status === 400 && !retriedThinking && includeThinking && /thinking/i.test(errMsg)) {
            includeThinking = false;
            retriedThinking = true;
            continue;
          }
          if (res.status === 400 && !retriedMaxTokens && currentMaxTokens > 8192 && /max_output_tokens|output token/i.test(errMsg)) {
            currentMaxTokens = 8192;
            retriedMaxTokens = true;
            continue;
          }
          break;
        }
        recordUsageTokens(data?.usage);
        let combinedText = extractTextFromInteraction(data, Boolean(responseSchema));
        let status = data?.status || "completed";
        let contToken = data?.continuation_token || null;
        let contCount = 0;
        let contFailed = false;
        while ((status === "requires_continuation" || status === "REQUIRES_CONTINUATION") && contToken && contCount < 2 && remainingBudgetMs() > 10000 && !isAborted()) {
          contCount += 1;
          diagnostics.generative_calls += 1;
          const contRes = await fetchWithTimeout(geminiDirectUrl, {
            method: "POST",
            headers,
            body: JSON.stringify(buildPayload(includeThinking, contToken))
          }, 18000);
          if (!contRes.ok) {
            contFailed = true;
            status = "incomplete";
            break;
          }
          const contData = await contRes.json();
          recordUsageTokens(contData?.usage);
          combinedText += extractTextFromInteraction(contData, false);
          status = contData?.status || "completed";
          contToken = contData?.continuation_token || null;
        }
        if (status === "incomplete" || contFailed) diagnostics.incomplete_generations += 1;
        return {
          ok: combinedText.length > 0 && status !== "failed",
          text: combinedText,
          status,
          error: status === "failed" ? data?.error?.message || "interaction_failed" : null
        };
      } catch (err) {
        lastError = err.message || "fetch_exception";
        break;
      }
    }
    return { ok: false, text: "", status: "failed", error: lastError };
  }

  async function callDecisions(inputBlocks, questionsMap, timeoutMs = 18000) {
    if (!geminiApiKey || verificationEngine === "off" || verificationEngine === "generative_fallback") {
      return { ok: false, answers: null, error: "decisions_disabled_or_missing_key" };
    }
    if (decisionsCircuitOpen) {
      return { ok: false, answers: null, error: "decisions_circuit_open" };
    }
    if (isAborted()) {
      return { ok: false, answers: null, error: "aborted_by_caller" };
    }
    const qKeys = Object.keys(questionsMap || {});
    if (qKeys.length === 0 || qKeys.length > 1000) {
      return { ok: false, answers: null, error: "invalid_question_count" };
    }
    diagnostics.decisions_api_calls += 1;
    const headers = {
      "Content-Type": "application/json",
      "x-goog-api-key": geminiApiKey
    };
    const payload = {
      model: "gemini-decision-1",
      input: inputBlocks,
      questions: questionsMap
    };
    let lastErr = "decisions_unreachable";
    let shouldOpenCircuit = false;
    try {
      const res = await fetchWithTimeout(decisionsDirectUrl, {
        method: "POST",
        headers,
        body: JSON.stringify(payload)
      }, timeoutMs);
      const raw = await res.text();
      let data = null;
      try { data = JSON.parse(raw); } catch (e) {}
      if (res.ok && data && data.answers) {
        recordUsageTokens(data.usage);
        diagnostics.decisions_api_status = "healthy";
        return { ok: true, answers: data.answers, error: null };
      }
      const errCode = data?.error?.code || `HTTP_${res.status}`;
      const errMsg = data?.error?.message || raw.slice(0, 220);
      lastErr = `${errCode}: ${errMsg}`;
      if (res.status === 401 || res.status === 403 || res.status === 404 || res.status >= 500) {
        shouldOpenCircuit = true;
      }
    } catch (e) {
      lastErr = e.message || "decisions_network_error";
      shouldOpenCircuit = true;
    }
    if (shouldOpenCircuit) decisionsCircuitOpen = true;
    diagnostics.decisions_api_status = `degraded (${lastErr.slice(0, 120)})`;
    return { ok: false, answers: null, error: lastErr };
  }

